<?php
declare(strict_types=1);
require_once dirname(__DIR__) . '/private/short-links-tool.php';
kssmi_admin_require_trusted_proxy(); kssmi_short_links_session();
header("Content-Security-Policy: default-src 'self'; frame-ancestors 'none'; base-uri 'none'; form-action 'self'"); header('Link: </assets/short-links.css>; rel=stylesheet'); header('X-Robots-Tag: noindex, nofollow'); header('Cache-Control: no-store, private');
$message = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    if (!kssmi_admin_csrf_valid($_POST['csrf_token'] ?? null, 'short_links_tool_csrf')) { $message = 'Security check failed.'; }
    elseif (isset($_POST['logout'])) { unset($_SESSION['short_links_tool_auth'], $_SESSION['short_links_tool_email'], $_SESSION['short_links_tool_admin']); $message = 'Signed out.'; }
    elseif (isset($_POST['login']) && kssmi_short_links_login((string)($_POST['email'] ?? ''), (string)($_POST['password'] ?? ''))) { header('Location: /short-links'); exit; }
    else { $message = 'Invalid email or password.'; }
}
$identity = kssmi_short_links_identity(); $csrf = kssmi_short_links_csrf(); $reset = (string)($_GET['reset'] ?? '');
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>KSSMI Short Links</title><style>:root{--ink:#172033;--muted:#68738a;--line:#e5e9f0;--brand:#1459d9;--soft:#f4f7fc;--danger:#a83232}*{box-sizing:border-box}body{margin:0;min-height:100vh;font:15px/1.55 Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;color:var(--ink);background:linear-gradient(135deg,#f7f9fd,#edf3ff)}button,input{font:inherit}button{cursor:pointer}.shell{width:min(1120px,calc(100% - 40px));margin:auto;padding:28px 0 56px}.brand{display:flex;align-items:center;gap:12px;font-weight:750}.brand-mark{display:grid;place-items:center;width:38px;height:38px;border-radius:12px;color:#fff;background:linear-gradient(145deg,#2374f0,#0b3e9e);box-shadow:0 8px 18px #1459d933}.brand small{display:block;color:var(--muted);font-size:12px;font-weight:500}.card{border:1px solid var(--line);border-radius:22px;background:#fff;box-shadow:0 22px 65px #24477d14}.login-layout{display:grid;grid-template-columns:1.05fr .95fr;overflow:hidden;margin:54px auto 0;max-width:980px}.intro{position:relative;padding:58px;color:#fff;background:radial-gradient(circle at 12% 10%,#5b9aff,#286ee5 26%,#123c97)}.intro h1{margin:0 0 18px;max-width:420px;font-size:clamp(30px,4vw,46px);line-height:1.08;letter-spacing:-.04em}.intro p{max-width:390px;margin:0;color:#dce9ff;font-size:16px}.intro-list{display:grid;gap:14px;margin:42px 0 0;padding:0;list-style:none;color:#eaf2ff}.intro-list li:before{content:"✓";display:inline-grid;place-items:center;width:22px;height:22px;margin-right:10px;border-radius:50%;background:#ffffff24}.login-panel{padding:52px}.eyebrow{margin:0 0 8px;color:var(--brand);font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase}.login-panel h2{margin:0;font-size:28px;letter-spacing:-.03em}.subtle{margin:9px 0 28px;color:var(--muted)}.field{display:block;margin:0 0 17px}.field span{display:block;margin:0 0 7px;font-size:13px;font-weight:700}.field input{width:100%;height:46px;padding:0 14px;border:1px solid #d6dce7;border-radius:10px;outline:0;background:#fbfcfe}.field input:focus{border-color:#4c85e8;box-shadow:0 0 0 4px #4c85e81c}.primary{width:100%;height:46px;border:0;border-radius:10px;color:#fff;background:linear-gradient(135deg,#216ce8,#1248b9);font-weight:750;box-shadow:0 8px 18px #1459d92e}.divider{display:flex;align-items:center;gap:12px;margin:28px 0 20px;color:#9aa4b5;font-size:12px}.divider:before,.divider:after{content:"";height:1px;flex:1;background:var(--line)}.reset-box{padding:18px;border:1px solid var(--line);border-radius:13px;background:var(--soft)}.reset-box h3{margin:0 0 4px;font-size:14px}.reset-box p{margin:0 0 13px;color:var(--muted);font-size:13px}.reset-row{display:flex;gap:8px}.reset-row input{min-width:0;flex:1;height:40px;padding:0 11px;border:1px solid #d6dce7;border-radius:8px}.secondary{height:40px;padding:0 13px;border:1px solid #cbd5e5;border-radius:8px;background:#fff;color:var(--brand);font-weight:700;white-space:nowrap}.alert{margin:0 auto 18px;padding:12px 14px;border:1px solid #f1caca;border-radius:10px;background:#fff4f4;color:var(--danger)}.box{margin:16px 0;padding:24px;border:1px solid var(--line);border-radius:16px;background:#fff;box-shadow:0 10px 30px #24477d0a}@media(max-width:760px){.shell{width:min(100% - 24px,560px);padding-top:18px}.login-layout{display:block;margin-top:30px}.intro{padding:32px 28px}.intro h1{font-size:34px}.intro-list{margin-top:26px}.login-panel{padding:32px 28px}.reset-row{display:block}.reset-row input,.reset-row .secondary{width:100%}.reset-row .secondary{margin-top:8px}}</style></head><body><main class="shell"><div class="brand"><span class="brand-mark">↗</span><span>KSSMI <small>Short Links</small></span></div><?php if ($message): ?><div class="alert" role="alert"><?php echo htmlspecialchars($message); ?></div><?php endif; ?>
<?php if (!$identity): ?><style>body:has(.login-simple) .brand{display:none}body:has(.login-simple) .shell{min-height:100vh;display:grid;place-items:center;padding:24px}.login-simple{width:min(100%,390px);padding:34px;border-radius:14px;text-align:left}.login-simple h1{margin:0 0 4px;font-size:22px;letter-spacing:-.02em}.login-simple .login-note{margin:0 0 26px;color:var(--muted);font-size:14px}.login-simple .field{margin-bottom:15px}.login-simple .primary{margin-top:4px}.login-simple details{margin-top:22px;border-top:1px solid var(--line);padding-top:16px}.login-simple summary{color:var(--brand);font-size:13px;cursor:pointer}.login-simple .reset-box{margin-top:14px}.login-simple .reset-row{display:block}.login-simple .reset-row input{width:100%;margin-bottom:8px}.login-simple .secondary{width:100%}</style><section class="card login-simple"><h1>KSSMI Short Links</h1><p class="login-note">Sign in to continue.</p><form method="post" autocomplete="on"><input type="hidden" name="csrf_token" value="<?php echo htmlspecialchars($csrf); ?>"><label class="field"><span>Email</span><input name="email" type="email" autocomplete="username" placeholder="you@kssmi.com" required></label><label class="field"><span>Password</span><input name="password" type="password" autocomplete="current-password" required></label><button class="primary" name="login" value="1" type="submit">Sign in</button></form><details><summary>Forgot password?</summary><div class="reset-box"><p>Enter your account email to receive a reset link.</p><form class="reset-row" method="post" action="/api/short-links-reset.php"><input type="hidden" name="csrf_token" value="<?php echo htmlspecialchars($csrf); ?>"><input type="hidden" name="action" value="request"><input name="email" type="email" placeholder="Account email" autocomplete="email" required><button class="secondary" type="submit">Send reset link</button></form></div></details></section>
<?php if ($reset !== ''): ?><div class="box"><h2>Set a new password</h2><form method="post" action="/api/short-links-reset.php"><input type="hidden" name="csrf_token" value="<?php echo htmlspecialchars($csrf); ?>"><input type="hidden" name="action" value="confirm"><input type="hidden" name="token" value="<?php echo htmlspecialchars($reset); ?>"><input name="password" type="password" minlength="10" maxlength="128" placeholder="New password" required><button>Save password</button></form></div><?php endif; ?>
<?php else: ?><p>Signed in as <strong><?php echo htmlspecialchars($identity['email']); ?></strong> <?php if ($identity['admin']) echo '(admin)'; ?><form method="post" style="display:inline"><input type="hidden" name="csrf_token" value="<?php echo htmlspecialchars($csrf); ?>"><button name="logout" value="1">Sign out</button></form></p><div class="box"><h2>Create a short link</h2><form id="create"><input name="target_url" type="url" placeholder="https://example.com/..." size="55" required><input name="label" placeholder="Label"><input name="campaign" placeholder="Campaign"><input name="recipient_ref" placeholder="Recipient"><button>Create</button></form><p id="result"></p></div><div class="box"><h2>Your links<?php if($identity['admin']) echo ' (all accounts)'; ?></h2><input id="search" placeholder="Search"><button onclick="load()">Search</button><table><thead><tr><th>Code</th><th>Target</th><th>By</th><th>Opens</th><th>Actions</th></tr></thead><tbody id="rows"></tbody></table></div><script>const csrf=<?php echo json_encode($csrf); ?>;async function api(action,data={}){let r=await fetch('/api/short-links-tool.php',{method:'POST',headers:{'Content-Type':'application/json','Origin':location.origin,'Sec-Fetch-Site':'same-origin'},body:JSON.stringify({action,csrf_token:csrf,...data})});let b=await r.json();if(!r.ok)throw Error(b.error||'Request failed');return b}async function load(){try{let b=await api('list',{search:document.getElementById('search').value});document.getElementById('rows').innerHTML=b.rows.map(x=>`<tr><td><a href="/${x.code}">${x.code}</a></td><td>${x.target_url}</td><td>${x.created_by||''}</td><td>${x.opens||0}</td><td><button onclick="del(${x.id},'${x.code}')">Delete</button></td></tr>`).join('')}catch(e){alert(e.message)}}async function del(id,code){if(!confirm('Delete '+code+'?'))return;try{await api('permanent-delete',{id,confirmation:'DELETE '+code});load()}catch(e){alert(e.message)}}document.getElementById('create').onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));try{let x=await api('destination',{target_url:d.target_url});let id=x.destination.id;let y=await api('distribution',{destination_id:id,label:d.label,campaign:d.campaign,recipient_ref:d.recipient_ref});document.getElementById('result').textContent='Created: https://kssmi.com/'+y.link.code;load()}catch(e){document.getElementById('result').textContent=e.message}};load();</script><?php endif; ?></main></body></html>
